%% pv_string_validation.m
%  Validate a 4-module PV string under uniform and partial shading.
%
%  Demonstrates:
%    1. Uniform irradiance — string Voc = 4×Voc_mod, Isc unchanged, Pmpp = 4×Pmpp_mod
%    2. Partial shading — multi-peak P-V curves, bypass diode activation
%    3. Per-module voltage distribution under shading
%
%  Panel: AIKO Neostar A555 (555 W), 4 modules in series

clear; clc; close all;

SAVE_DIR = 'figures';
if ~exist(SAVE_DIR, 'dir'), mkdir(SAVE_DIR); end

%% ========================================================================
%  PANEL PARAMETERS
%  ========================================================================
ds.Isc  = 14.96;   ds.Voc  = 45.90;
ds.Impp = 14.35;   ds.Vmpp = 38.70;
ds.Pmpp = 555;     ds.Ns   = 60;
ds.ki   = 0.05;    ds.kv   = -0.22;
ds.Tstc = 298.15;

mod.A   = 1.0;     mod.Rs  = 0.158;
mod.Rsh = 51807;   mod.I0  = 1.7528e-12;
mod.Iph = 14.96;

N_mod    = 4;          % Modules in series
V_bypass = 0.7;        % Bypass diode forward voltage [V]
T_cell   = 25;         % Cell temperature [°C]

q_ = 1.602176634e-19;
k_ = 1.380649e-23;

%% ========================================================================
%  SHADING SCENARIOS
%  ========================================================================
%  Each row = irradiance [W/m²] for modules [M3, M2, M1, M0] (top to bottom)
scenarios = {
    'Uniform 1000 W/m²',           [1000 1000 1000 1000];
    'One module shaded (500)',      [1000 1000 1000  500];
    'One module heavy shade (200)', [1000 1000 1000  200];
    'Two modules shaded',          [1000 1000  500  500];
    'Graduated shading',           [1000  800  500  200];
};

%% ========================================================================
%  STRING I-V SOLVER
%  ========================================================================
%  For a series string with bypass diodes:
%    - Sweep string current from 0 to max Isc
%    - At each current, find each module's voltage from its I-V curve
%    - If the module can't supply the current (I > Isc_module), its bypass
%      diode activates and that module contributes -V_bypass
%    - String voltage = sum of all module voltages

fprintf('================================================================\n'); %[output:167cac2d]
fprintf('  PV String Validation — %d × AIKO A555 (%d W)\n', N_mod, ds.Pmpp); %[output:4bc81357]
fprintf('================================================================\n\n'); %[output:29476bd4]

results = struct([]);

for sc = 1:size(scenarios, 1) %[output:group:87d5af22]
    name = scenarios{sc, 1};
    G_vec = scenarios{sc, 2};

    fprintf('--- %s: G = [%s] W/m² ---\n', name, num2str(G_vec)); %[output:6b43cf0d] %[output:4dc12e0f] %[output:68e414b8] %[output:5784338b] %[output:39ee5697]

    % Precompute each module's I-V curve
    mod_curves = struct([]);
    max_Isc = 0;
    for mm = 1:N_mod
        [I_m, V_m, ~] = pv_module_iv(ds, mod, G_vec(mm), T_cell);
        mod_curves(mm).V = V_m;
        mod_curves(mm).I = I_m;
        mod_curves(mm).Isc = I_m(1);
        mod_curves(mm).Voc = V_m(find(I_m > 0.01, 1, 'last'));
        if I_m(1) > max_Isc
            max_Isc = I_m(1);
        end
    end

    % Sweep string current
    I_sweep = linspace(max_Isc, 0, 2000);
    V_string = zeros(size(I_sweep));
    V_modules = zeros(N_mod, length(I_sweep));
    bypassed  = false(N_mod, length(I_sweep));

    for ii = 1:length(I_sweep)
        I_str = I_sweep(ii);
        for mm = 1:N_mod
            if I_str > mod_curves(mm).Isc
                % Bypass diode activates
                V_modules(mm, ii) = -V_bypass;
                bypassed(mm, ii) = true;
            else
                % Find voltage on this module's I-V curve at this current
                % Interpolate: V = f(I), but I-V is not monotonic in V
                % Use the portion where I is decreasing (normal operation)
                idx_valid = mod_curves(mm).I >= 0;
                V_mod_valid = mod_curves(mm).V(idx_valid);
                I_mod_valid = mod_curves(mm).I(idx_valid);

                % I is monotonically decreasing with V in normal operation
                % Flip for interp1 (needs increasing x)
                [I_sorted, sort_idx] = unique(I_mod_valid, 'stable');
                V_sorted = V_mod_valid(sort_idx);

                % interp1 needs strictly monotonic — flip since I decreases
                I_flip = flip(I_sorted);
                V_flip = flip(V_sorted);

                % Remove any non-unique values
                [I_uniq, uniq_idx] = unique(I_flip);
                V_uniq = V_flip(uniq_idx);

                if I_str <= max(I_uniq) && I_str >= min(I_uniq)
                    V_modules(mm, ii) = interp1(I_uniq, V_uniq, I_str, 'linear');
                elseif I_str < min(I_uniq)
                    V_modules(mm, ii) = mod_curves(mm).Voc;
                else
                    V_modules(mm, ii) = -V_bypass;
                    bypassed(mm, ii) = true;
                end
            end
        end
        V_string(ii) = sum(V_modules(:, ii));
    end

    % Clamp negative string voltages
    valid = V_string >= 0 & I_sweep >= 0;
    I_str_valid = I_sweep(valid);
    V_str_valid = V_string(valid);
    P_str_valid = V_str_valid .* I_str_valid;

    [Pmpp_str, idx_mpp] = max(P_str_valid);
    Vmpp_str = V_str_valid(idx_mpp);
    Impp_str = I_str_valid(idx_mpp);
    Voc_str  = max(V_str_valid);
    Isc_str  = max(I_str_valid);

    results(sc).name    = name;
    results(sc).G       = G_vec;
    results(sc).I       = I_str_valid;
    results(sc).V       = V_str_valid;
    results(sc).P       = P_str_valid;
    results(sc).Pmpp    = Pmpp_str;
    results(sc).Vmpp    = Vmpp_str;
    results(sc).Impp    = Impp_str;
    results(sc).Voc     = Voc_str;
    results(sc).Isc     = Isc_str;
    results(sc).V_mods  = V_modules(:, valid);
    results(sc).bypassed = bypassed(:, valid);

    fprintf('  Isc  = %.2f A   Voc  = %.1f V\n', Isc_str, Voc_str); %[output:805fd8e0] %[output:7f35a419] %[output:118b7a19] %[output:3ae2ef28] %[output:85f6adc7]
    fprintf('  Pmpp = %.1f W   Vmpp = %.1f V   Impp = %.2f A\n', ... %[output:550aa6ea] %[output:16b8983a] %[output:0a158e8a] %[output:1e773f06] %[output:461c444e]
            Pmpp_str, Vmpp_str, Impp_str); %[output:550aa6ea] %[output:16b8983a] %[output:0a158e8a] %[output:1e773f06] %[output:461c444e]
    fprintf('  Bypass events: %s\n\n', ... %[output:20a89848] %[output:0a1124a4] %[output:4edfd6f5] %[output:10323cb7] %[output:1e2e3de7]
            mat2str(any(bypassed, 2)')); %[output:20a89848] %[output:0a1124a4] %[output:4edfd6f5] %[output:10323cb7] %[output:1e2e3de7]
end %[output:group:87d5af22]

%% ========================================================================
%  FIGURE 1 — STRING I-V: ALL SCENARIOS
%  ========================================================================
cmap = lines(size(scenarios, 1));

fig1 = figure('Name','String I-V','Position',[50 50 750 520]); %[output:0c68ad96]
hold on; %[output:0c68ad96]
h_iv = gobjects(size(scenarios, 1), 1);
for sc = 1:size(scenarios, 1)
    h_iv(sc) = plot(results(sc).V, results(sc).I, '-', ... %[output:0c68ad96]
         'Color', cmap(sc,:), 'LineWidth', 2); %[output:0c68ad96]
    plot(results(sc).Vmpp, results(sc).Impp, 'o', ...
         'Color', cmap(sc,:), 'MarkerSize', 8, ...
         'MarkerFaceColor', 'w', 'LineWidth', 1.5, ...
         'HandleVisibility', 'off');
end
xlabel('String Voltage [V]', 'FontSize', 12); %[output:0c68ad96]
ylabel('String Current [A]', 'FontSize', 12); %[output:0c68ad96]
title(sprintf('PV String I-V — %d × AIKO A555 in Series', N_mod), 'FontSize', 13); %[output:0c68ad96]
legend(h_iv, scenarios(:,1), 'Location', 'southwest', 'FontSize', 9); %[output:0c68ad96]
grid on; xlim([0 200]); ylim([0 17]); %[output:0c68ad96]
set(gca, 'FontSize', 11); %[output:0c68ad96]
exportgraphics(fig1, fullfile(SAVE_DIR, 'string_IV_shading.pdf'), 'ContentType', 'vector'); %[output:0c68ad96]
fprintf('Saved: %s\n', fullfile(SAVE_DIR, 'string_IV_shading.pdf')); %[output:523f8f11]

%% ========================================================================
%  FIGURE 2 — STRING P-V: ALL SCENARIOS (shows multi-peak under shading)
%  ========================================================================
fig2 = figure('Name','String P-V','Position',[820 50 750 520]); %[output:5c608334]
hold on; %[output:5c608334]
h_pv = gobjects(size(scenarios, 1), 1);
for sc = 1:size(scenarios, 1)
    h_pv(sc) = plot(results(sc).V, results(sc).P, '-', ... %[output:5c608334]
         'Color', cmap(sc,:), 'LineWidth', 2); %[output:5c608334]
    plot(results(sc).Vmpp, results(sc).Pmpp, 'o', ...
         'Color', cmap(sc,:), 'MarkerSize', 8, ...
         'MarkerFaceColor', 'w', 'LineWidth', 1.5, ...
         'HandleVisibility', 'off');
    text(results(sc).Vmpp + 2, results(sc).Pmpp, ...
         sprintf('%.0f W', results(sc).Pmpp), ...
         'Color', cmap(sc,:), 'FontSize', 9, 'FontWeight', 'bold');
end
xlabel('String Voltage [V]', 'FontSize', 12); %[output:5c608334]
ylabel('String Power [W]', 'FontSize', 12); %[output:5c608334]
title(sprintf('PV String P-V — Partial Shading Effects', N_mod), 'FontSize', 13); %[output:5c608334]
legend(h_pv, scenarios(:,1), 'Location', 'northwest', 'FontSize', 9); %[output:5c608334]
grid on; xlim([0 200]); ylim([0 2500]); %[output:5c608334]
set(gca, 'FontSize', 11); %[output:5c608334]
exportgraphics(fig2, fullfile(SAVE_DIR, 'string_PV_shading.pdf'), 'ContentType', 'vector'); %[output:5c608334] %[output:3a4ed4c1]
fprintf('Saved: %s\n', fullfile(SAVE_DIR, 'string_PV_shading.pdf')); %[output:2b48ae9e]

%% ========================================================================
%  FIGURE 3 — UNIFORM vs SINGLE-MODULE COMPARISON
%  ========================================================================
fig3 = figure('Name','String vs Module','Position',[50 600 750 520]); %[output:872ad790]

% Single module at STC
[I_1mod, V_1mod, P_1mod] = pv_module_iv(ds, mod, 1000, 25);

subplot(1,2,1); hold on; %[output:872ad790]
plot(V_1mod, I_1mod, 'b-', 'LineWidth', 2); %[output:872ad790]
plot(results(1).V, results(1).I, 'r--', 'LineWidth', 2); %[output:872ad790]
xlabel('Voltage [V]'); ylabel('Current [A]'); %[output:872ad790]
title('I-V: Module vs String'); %[output:872ad790]
legend('Single module', sprintf('%d-module string', N_mod), 'Location', 'southwest'); %[output:872ad790]
grid on; ylim([0 17]); %[output:872ad790]

subplot(1,2,2); hold on; %[output:872ad790]
plot(V_1mod, P_1mod, 'b-', 'LineWidth', 2); %[output:872ad790]
plot(results(1).V, results(1).P, 'r--', 'LineWidth', 2); %[output:872ad790]
xlabel('Voltage [V]'); ylabel('Power [W]'); %[output:872ad790]
title('P-V: Module vs String'); %[output:872ad790]
legend('Single module', sprintf('%d-module string', N_mod), 'Location', 'northwest'); %[output:872ad790]
grid on; %[output:872ad790]

sgtitle('Uniform 1000 W/m² — Voltage Scales, Current Preserved', 'FontWeight', 'bold'); %[output:872ad790]
exportgraphics(fig3, fullfile(SAVE_DIR, 'string_vs_module.pdf'), 'ContentType', 'vector'); %[output:872ad790]
fprintf('Saved: %s\n', fullfile(SAVE_DIR, 'string_vs_module.pdf')); %[output:50db7bde]

%% ========================================================================
%  FIGURE 4 — PER-MODULE VOLTAGE UNDER GRADUATED SHADING
%  ========================================================================
sc_grad = 5;  % Graduated shading scenario
fig4 = figure('Name','Per-Module Voltage','Position',[820 600 750 520]); %[output:474d854e]

V_str_plot = results(sc_grad).V;
V_mods_plot = results(sc_grad).V_mods;
bp_plot = results(sc_grad).bypassed;

hold on; %[output:474d854e]
mod_colors = [0.85 0 0; 0 0.6 0; 0 0 0.85; 0.6 0 0.6];
mod_labels = {'M3 (1000)', 'M2 (800)', 'M1 (500)', 'M0 (200)'};
h_mods = gobjects(N_mod, 1);

for mm = 1:N_mod
    h_mods(mm) = plot(V_str_plot, V_mods_plot(mm,:), '-', ... %[output:474d854e]
         'Color', mod_colors(mm,:), 'LineWidth', 1.8); %[output:474d854e]
end

% Mark bypass regions
for mm = 1:N_mod
    bp_regions = V_mods_plot(mm,:) < 0;
    if any(bp_regions)
        bp_V = V_str_plot(bp_regions);
        if ~isempty(bp_V)
            xline(min(bp_V), '--', sprintf('M%d bypass', N_mod-mm), ... %[output:474d854e]
                  'Color', mod_colors(mm,:), 'LineWidth', 1, ... %[output:474d854e]
                  'LabelOrientation', 'horizontal', ... %[output:474d854e]
                  'HandleVisibility', 'off'); %[output:474d854e]
        end
    end
end

xlabel('String Voltage [V]', 'FontSize', 12); %[output:474d854e]
ylabel('Per-Module Voltage [V]', 'FontSize', 12); %[output:474d854e]
title(sprintf('Per-Module Voltage — %s', results(sc_grad).name), 'FontSize', 13); %[output:474d854e]
legend(h_mods, mod_labels, 'Location', 'northwest', 'FontSize', 10); %[output:474d854e]
grid on; xlim([0 200]); %[output:474d854e]
set(gca, 'FontSize', 11); %[output:474d854e]
exportgraphics(fig4, fullfile(SAVE_DIR, 'per_module_voltage_shading.pdf'), 'ContentType', 'vector'); %[output:474d854e]
fprintf('Saved: %s\n', fullfile(SAVE_DIR, 'per_module_voltage_shading.pdf')); %[output:34b151ad]

%% ========================================================================
%  FIGURE 5 — SHADING LOSS SUMMARY BAR CHART
%  ========================================================================
fig5 = figure('Name','Shading Losses','Position',[400 300 600 400]); %[output:8d5ff9e1]

P_uniform = results(1).Pmpp;
P_vals = arrayfun(@(r) r.Pmpp, results);
P_loss_pct = 100 * (P_uniform - P_vals) / P_uniform;

barh(1:size(scenarios,1), P_vals, 'FaceColor', [0.2 0.6 0.9]); hold on; %[output:8d5ff9e1]
barh(1:size(scenarios,1), P_vals, 'FaceColor', 'flat', ... %[output:8d5ff9e1]
     'CData', cmap(1:size(scenarios,1),:)); %[output:8d5ff9e1]
set(gca, 'YTick', 1:size(scenarios,1), 'YTickLabel', scenarios(:,1)); %[output:8d5ff9e1]
xlabel('String Pmpp [W]', 'FontSize', 12); %[output:8d5ff9e1]
title('Shading Impact on Maximum Power', 'FontSize', 13); %[output:8d5ff9e1]
xlim([0 2500]); %[output:8d5ff9e1]

for ii = 1:size(scenarios, 1)
    if P_loss_pct(ii) > 0
        text(P_vals(ii) + 30, ii, sprintf('-%.1f%%', P_loss_pct(ii)), ...
             'FontSize', 10, 'FontWeight', 'bold', 'Color', [0.7 0 0]);
    else
        text(P_vals(ii) + 30, ii, 'Baseline', ... %[output:8d5ff9e1]
             'FontSize', 10, 'Color', [0 0.5 0]); %[output:8d5ff9e1]
    end
end
set(gca, 'FontSize', 10); %[output:8d5ff9e1]
exportgraphics(fig5, fullfile(SAVE_DIR, 'shading_loss_summary.pdf'), 'ContentType', 'vector'); %[output:8d5ff9e1]
fprintf('Saved: %s\n', fullfile(SAVE_DIR, 'shading_loss_summary.pdf')); %[output:10fb62bc]

%% ========================================================================
%  CONSOLE SUMMARY TABLE
%  ========================================================================
fprintf('\n================================================================\n'); %[output:873441fc]
fprintf('  STRING PERFORMANCE SUMMARY\n'); %[output:57eb064d]
fprintf('================================================================\n'); %[output:660274ec]
fprintf('%-30s %8s %8s %8s %8s %8s\n', 'Scenario', 'Isc[A]', 'Voc[V]', 'Pmpp[W]', 'Vmpp[V]', 'Loss'); %[output:98dc2eb0]
for sc = 1:size(scenarios, 1) %[output:group:798eceff]
    if sc == 1
        loss_str = '  —';
    else
        loss_str = sprintf('%5.1f%%', P_loss_pct(sc));
    end
    fprintf('%-30s %8.2f %8.1f %8.1f %8.1f %8s\n', ... %[output:6c4efd9a]
            results(sc).name, results(sc).Isc, results(sc).Voc, ... %[output:6c4efd9a]
            results(sc).Pmpp, results(sc).Vmpp, loss_str); %[output:6c4efd9a]
end %[output:group:798eceff]
fprintf('================================================================\n'); %[output:99fa5da5]
fprintf('\nExpected uniform string values:\n'); %[output:9b53a800]
fprintf('  Isc  = %.2f A  (same as single module)\n', ds.Isc); %[output:6349b834]
fprintf('  Voc  = %.1f V  (%d × %.1f V)\n', N_mod*ds.Voc, N_mod, ds.Voc); %[output:434d07bc]
fprintf('  Pmpp = %d W  (%d × %d W)\n', N_mod*ds.Pmpp, N_mod, ds.Pmpp); %[output:777c5d86]
fprintf('\nAll figures saved to: %s/\n', SAVE_DIR); %[output:26e3468c]

%% ========================================================================
%  HELPER: Single module I-V at given G and T
%  ========================================================================
function [I_out, V_out, P_out] = pv_module_iv(ds, mod, G, T_degC)
    q_ = 1.602176634e-19;  k_ = 1.380649e-23;
    T    = T_degC + 273.15;
    nsVt = ds.Ns * mod.A * k_ * T / q_;

    Isc_T  = ds.Isc * (1 + ds.ki/100 * (T - ds.Tstc));
    Voc_T  = ds.Voc * (1 + ds.kv/100 * (T - ds.Tstc));
    Io_T   = (Isc_T - (Voc_T - Isc_T*mod.Rs)/mod.Rsh) * exp(-Voc_T/nsVt);
    if Io_T <= 0, Io_T = ds.Isc * exp(-ds.Voc/nsVt); end
    Iph_T  = Io_T * exp(Voc_T/nsVt) + Voc_T/mod.Rsh;
    Iph_GT = Iph_T * (G / 1000);

    Voc_GT = max(Voc_T, 0.1);
    for nn = 1:50
        f_  = Iph_GT - Io_T*exp(Voc_GT/nsVt) - Voc_GT/mod.Rsh;
        fp_ = -Io_T/nsVt*exp(Voc_GT/nsVt) - 1/mod.Rsh;
        dV  = -f_/fp_;
        Voc_GT = Voc_GT + dV;
        if abs(dV) < 1e-8, break; end
    end

    V_out = linspace(0, max(Voc_GT, 0), 1000);
    I_out = zeros(size(V_out));
    opts  = optimset('Display','off','TolX',1e-12);
    for ii = 1:length(V_out)
        Vk = V_out(ii);
        fun = @(Ik) Iph_GT - Io_T*(exp((Vk+Ik*mod.Rs)/nsVt)-1) ...
                    - (Vk+Ik*mod.Rs)/mod.Rsh - Ik;
        try
            I_out(ii) = fzero(fun, max(Iph_GT - Vk/mod.Rsh, 0), opts);
        catch
            I_out(ii) = 0;
        end
    end
    I_out(I_out < 0) = 0;
    P_out = V_out .* I_out;
end

